import{_ as a,o as t,c as o,a3 as s}from"./chunks/framework.B8xISX-C.js";const p=JSON.parse('{"title":"Sharing","description":"","frontmatter":{"title":"Sharing"},"headers":[],"relativePath":"guide/sharing.md","filePath":"guide/sharing.md"}'),r={name:"guide/sharing.md"};function i(d,e,n,h,l,c){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="sharing" tabindex="-1">Sharing <a class="header-anchor" href="#sharing" aria-label="Permalink to &quot;Sharing&quot;">​</a></h1><p>This page covers how players get your mod: as a file, from the mod catalog or from a page you host.</p><h2 id="a-file" tabindex="-1">A file <a class="header-anchor" href="#a-file" aria-label="Permalink to &quot;A file&quot;">​</a></h2><p><code>npx carina-modkit pack mods/&lt;mod&gt;</code> writes the <code>.carinamod</code>. Give it to players with its sha256, which <code>pack</code> prints. A player imports it with MODS, then IMPORT.</p><p>Every mod you share follows <a href="https://github.com/jkirsteins/carina-mod-template/blob/main/CONTENT_POLICY.md" target="_blank" rel="noreferrer">content policy</a>: your own work, or work whose licence allows it, and nothing taken from other games. Set a <code>license</code> in <code>mod.json</code>, and <code>sources</code> for outside material.</p><h2 id="the-mod-catalog" tabindex="-1">The mod catalog <a class="header-anchor" href="#the-mod-catalog" aria-label="Permalink to &quot;The mod catalog&quot;">​</a></h2><p>The game&#39;s mod catalog is a curated list. Players find it in the game: MODS, then ONLINE CATALOG. INSTALL installs the mod, with the mods it needs.</p><p>To get listed, open a pull request or a <strong>Submit a mod</strong> issue in the <a href="https://github.com/jkirsteins/carina-mods" target="_blank" rel="noreferrer">catalog repository</a>. Its SUBMITTING.md says how. You give:</p><ul><li>your <code>.carinamod</code> or a link to your mod&#39;s page,</li><li>the sha256 that <code>pack</code> printed.</li></ul><p>A pull request runs <code>npx carina-modkit@^0.2.0 catalog add &lt;your file&gt;</code> on the repository. Add <code>--page &lt;url&gt;</code> if you host the file yourself. The <code>validate</code> check must pass. The keeper reviews the mod, merges it and signs the catalog, and the game shows it within minutes.</p><p>The catalog stores packages of at most 20 MB.</p><h3 id="updates" tabindex="-1">Updates <a class="header-anchor" href="#updates" aria-label="Permalink to &quot;Updates&quot;">​</a></h3><p>A listed file never changes. Pack a new version and submit it the same way. Players see an update notice in the game. See <a href="/carina-mod-template/guide/updates">Releasing an update</a>.</p><h2 id="external-pages" tabindex="-1">External pages <a class="header-anchor" href="#external-pages" aria-label="Permalink to &quot;External pages&quot;">​</a></h2><p>Bigger mods, and mods you prefer to host yourself, for example on itch.io, are listed as external pages. The catalog lists the page and the file&#39;s sha256.</p><p>In the game, a player:</p><ol><li>Selects the mod in ONLINE CATALOG and presses OPEN PAGE, or GET IT ON the host&#39;s name.</li><li>Gets the <code>.carinamod</code> there. The game says <code>Hosted on &lt;host&gt;: get the .carinamod there, then use IMPORT on the INSTALLED tab.</code></li><li>Imports it with IMPORT.</li></ol><p>The import report says whether the file matches the listed sha256.</p><h2 id="mods-that-need-other-mods" tabindex="-1">Mods that need other mods <a class="header-anchor" href="#mods-that-need-other-mods" aria-label="Permalink to &quot;Mods that need other mods&quot;">​</a></h2><p>A mod that lists a required dependency installs from ONLINE CATALOG together with it, when the catalog lists the dependency. If the catalog does not list it, INSTALL installs nothing and the detail pane says why. See <a href="/carina-mod-template/guide/dependencies">Dependencies and compatibility</a>.</p><p>A mod hosted on an external page cannot be installed as a dependency. The player installs it first.</p><h2 id="saves-and-rooms-that-need-your-mod" tabindex="-1">Saves and rooms that need your mod <a class="header-anchor" href="#saves-and-rooms-that-need-your-mod" aria-label="Permalink to &quot;Saves and rooms that need your mod&quot;">​</a></h2><p>A save or a multiplayer room that uses a mod a player lacks lists the mods that differ. GET FROM CATALOG installs them, with the mods they need, when the catalog lists the exact packages the save or room uses. A mod that is only in a file or on an external page is installed by hand with IMPORT.</p>',23)])])}const g=a(r,[["render",i]]);export{p as __pageData,g as default};
